import{z as i,x as A,o as r,c as d,q as l,j as o,D as t,d as E,s as n,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"活锁与饥饿","description":"","frontmatter":{"title":"活锁与饥饿","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/livelock-starvation.md","filePath":"cs/livelock-starvation.md","lastUpdated":1791063341000}'),p={name:"cs/livelock-starvation.md"};function m(c,a,C,D,h,f){const s=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=l('<h1 id="活锁与饥饿" tabindex="-1">活锁与饥饿 <a class="header-anchor" href="#活锁与饥饿" aria-label="Permalink to &quot;活锁与饥饿&quot;">​</a></h1><div class="epigraph"><p>活锁是大家都在变、却谁也做不成；饥饿是调度或锁策略永远不把资源分给某位等待者——两者都不是 Coffman 环。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Tanenbaum MOS 整理</footer></div><p><a href="/cs/banker-algorithm">上一课</a>用安全序列挡住走向死锁的分配。仍可能：协议互相「请对方先走」以至于无限重试，或低优先级/低权重永远选不上。缺口是把 <strong>活锁</strong>与<strong>饥饿</strong>从死锁里拆出来：图中无环，进度仍失败。<a href="/cs/fcfs-sjf">SJF</a> 与<a href="/cs/rwlock">rwlock</a> 已经点过饥饿，本课收成同步课的收口之一。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>死锁：等待集合永远不变。活锁：状态一直变（CAS 失败重来、以太网退避又碰撞、两人在走廊对让），没有人完成临界区。饥饿：系统整体有进度，某一个任务的等待无上界。缺口不是再跑银行家矩阵，而是<strong>进度的粒度</strong>：系统级、锁级、任务级。</p><p><span class="marginnote">直觉类比：死锁是两人各自攥住一根绳子不放；活锁是走廊里两个互相让路的人同时左让、同时右让，谁也过不去；饥饿是银行窗口一直在叫号办业务，唯独你的号牌被永远压在最底下。</span></p><p><span class="marginnote">无锁算法常保证无锁进度（有人能完成）而不保证无等待（每个人有限步完成）。后者失败可以是饥饿。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>活锁对策：随机退避、指定仲裁者、MCS 那种 FIFO 排队。饥饿对策：老化（等待越久优先级越高）、MLFQ 定期提升、写者优先 rwlock、CFS 的 vruntime 不让人的份额落到零。实时固定优先级<strong>故意</strong>允许低优先级饥饿，那是期限换来的。本课只对照，不改 RM 界限。</p><p><span class="marginnote">数字实例：老化常把有效优先级算成「基础优先级 + \\(k\\times\\) 等待时长」。取 \\(k=1\\)，低优任务等 100 毫秒就加 100，足以越过只等了 10 毫秒的高优任务——等待时长因此有了上界。</span></p>',10)),(r(),o(B,null,{default:t(()=>[n(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DL%5B%22%E6%AD%BB%E9%94%81%3A%20%E7%8E%AF%2C%20%E7%8A%B6%E6%80%81%E5%86%BB%E4%BD%8F%22%5D%20--%3E%20CONTRAST%5B%22%E5%AF%B9%E7%85%A7%22%5D%0A%20%20LL%5B%22%E6%B4%BB%E9%94%81%3A%20%E5%9C%A8%E5%8A%A8%E4%BD%86%E6%97%A0%E8%BF%9B%E5%B1%95%22%5D%20--%3E%20CONTRAST%0A%20%20ST%5B%22%E9%A5%A5%E9%A5%BF%3A%20%E6%95%B4%E4%BD%93%E5%9C%A8%E8%BF%9B%E5%B1%95%2C%20%E6%9F%90%E4%BD%8D%E6%B2%A1%E6%9C%89%22%5D%20--%3E%20CONTRAST%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[E("与"),e("a",{href:"/cs/restart-syscall"},"重启系统调用"),E("：无限 EINTR 循环若每次都失败，对应用也像活锁，那是信号政策。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"三种失败要不同工具：死锁查环或破条件；活锁改协议对称性；饥饿改公平或老化。银行家不管活锁：状态可以一直安全却没有人的请求被批准，若批准规则本身偏向某人。锁顺序下一课专管循环等待，不治饥饿。",-1)),(r(),o(B,null,{default:t(()=>[n(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20MEET%5B%22A%E3%80%81B%20%E5%90%8C%E6%97%B6%E8%B5%B0%E5%88%B0%E8%B5%B0%E5%BB%8A%E4%B8%AD%E9%97%B4%22%5D%20--%3E%20BOTH%5B%22%E5%8F%8C%E6%96%B9%E9%83%BD%E7%A4%BC%E8%B2%8C%E9%80%80%E8%AE%A9%22%5D%0A%20%20BOTH%20--%3E%20AGAIN%5B%22%E5%86%8D%E6%AC%A1%E5%AF%B9%E4%B8%8A%EF%BC%8C%E5%8F%88%E9%83%BD%E9%80%80%E8%AE%A9%EF%BC%9A%E6%97%A0%E9%99%90%E9%87%8D%E5%A4%8D%22%5D%0A%20%20AGAIN%20--%3E%20RND%5B%22%E9%80%80%E8%AE%A9%E5%89%8D%E5%85%88%E9%9A%8F%E6%9C%BA%E7%AD%89%E5%BE%85%E4%B8%80%E5%B0%8F%E6%AE%B5%22%5D%0A%20%20RND%20--%3E%20BREAK%5B%22%E7%AD%89%E5%BE%85%E6%97%B6%E9%95%BF%E4%B8%8D%E5%90%8C%EF%BC%8C%E7%BB%88%E4%BA%8E%E5%8F%AA%E6%9C%89%E4%B8%80%E6%96%B9%E9%80%80%22%5D%0A%20%20BREAK%20--%3E%20PASS%5B%22%E5%8F%A6%E4%B8%80%E6%96%B9%E9%80%9A%E8%BF%87%EF%BC%8C%E8%BF%9B%E5%BA%A6%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">常见误区：以为没有死锁环就一定安全。银行家只保证「不会冻住」；若批准规则偏向某些请求，其他请求照样无限等。安全（不冻住）与公平（每人都轮得到）是两回事，后者要靠 FIFO 或老化另加保证。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把以太网 CSMA 的全部历史当 OS 正文，不讨论如何用活锁做拒绝服务。也不把优先级反转单列为第四种：它更接近「有界或无界延迟」，可与饥饿重叠。</p><p>后课默认：无环也可以没有进度。预防循环等待的工程手段是全局锁序，下一课锁顺序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>活锁：在动无进展；饥饿：有人永远轮空；都不是死锁环。</li><li>对策分别是仲裁/FIFO 与老化/公平份额。</li><li>锁顺序破循环等待，下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',6))])}const T=i(p,[["render",m]]);export{S as __pageData,T as default};
